// Session-only display; deliberately has no persistence, diagnostics or transcript export.
[DefaultExecutionOrder(-200)]public sealed class RiftSessionChatHUD:MonoBehaviour {
 public static RiftSessionChatHUD Instance{get;private set;}public bool Writing{get;private set;}public byte Channel{get;private set;}public int BufferedCount=>lines.Count;public int ActiveBubbles=>bubbles.Count;public InputField Composer=>input;
