 readonly List<Line> lines=new List<Line>();readonly List<Bubble> bubbles=new List<Bubble>();RiftGameplayHUD hud;RectTransform root,viewport,historyRoot,bubbleLayer,invite,party;Text history,status,heading;InputField input;Button partyChannel;ScrollRect scroll;bool oldPauseAllowed,hadConnection;ChatUI legacy;bool oldLegacyEnabled;float statusUntil,nextExpire;
 public RectTransform Root=>root;
 RectTransform Rect(Transform p,string name,float x,float y,float w,float h){var r=new GameObject(name,typeof(RectTransform)).GetComponent<RectTransform>();r.SetParent(p,false);r.anchorMin=r.anchorMax=r.pivot=Vector2.up;r.anchoredPosition=new Vector2(x,-y);r.sizeDelta=new Vector2(w,h);return r;}
