 void Surface(RectTransform r,float alpha){var s=r.gameObject.AddComponent<RiftMapSurface>();s.Fill=new Color(.025f,.026f,.04f,alpha);s.Border=new Color(.39f,.32f,.5f,.55f);s.Radius=5;s.raycastTarget=false;}
