 void Awake(){Instance=this;hud=GetComponent<RiftGameplayHUD>();root=Rect(hud.Design,"Session proximity chat",20,0,340,140);root.anchorMin=root.anchorMax=root.pivot=Vector2.zero;root.anchoredPosition=new Vector2(20,22);Surface(root,.32f);Button(root,"Local",8,4,68,20,()=>SelectChannel(0));partyChannel=Button(root,"Party",80,4,68,20,()=>SelectChannel(1));Button(root,"Grupo",152,4,68,20,ToggleParty);heading=Label(root,"Local",228,6,104,18,10);
 viewport=Rect(root,"Ephemeral chat viewport",8,28,324,76);var mask=viewport.gameObject.AddComponent<RectMask2D>();historyRoot=Rect(viewport,"Ephemeral lines in memory",0,0,324,76);history=Label(historyRoot,"",0,0,324,76,12);scroll=viewport.gameObject.AddComponent<ScrollRect>();scroll.viewport=viewport;scroll.content=historyRoot;scroll.horizontal=false;scroll.movementType=ScrollRect.MovementType.Clamped;
 var entry=Rect(root,"Session chat composer",8,109,324,24);var bg=entry.gameObject.AddComponent<Image>();bg.color=new Color(.05f,.04f,.075f,.9f);input=entry.gameObject.AddComponent<InputField>();input.targetGraphic=bg;var value=Label(entry,"",6,1,312,22,12);input.textComponent=value;input.characterLimit=RiftSessionChatTuning.Load.Characters;input.lineType=InputField.LineType.SingleLine;var placeholder=Label(entry,"Enter: escribir · Esc: cancelar",6,1,312,22,11);placeholder.color=new Color(.67f,.65f,.73f);input.placeholder=placeholder;input.interactable=false;status=Label(root,"",8,91,324,17,10);
 bubbleLayer=Rect(hud.Design,"Authorized chat bubbles",0,0,1,1);bubbleLayer.anchorMin=Vector2.zero;bubbleLayer.anchorMax=Vector2.one;bubbleLayer.pivot=new Vector2(.5f,.5f);bubbleLayer.sizeDelta=bubbleLayer.anchoredPosition=Vector2.zero;ChatBehaviour.Received+=Receive;ChatBehaviour.Notice+=Notified;ChatBehaviour.PartyChanged+=PartyState;
 }
 void LegacyOff(){if(legacy==ChatUI.Instance)return;if(legacy)legacy.enabled=oldLegacyEnabled;legacy=ChatUI.Instance;if(legacy){oldLegacyEnabled=legacy.enabled;legacy.enabled=false;legacy.ChatWriting=false;}}
 public void SelectChannel(byte channel){if(channel>1||channel==1&&ChatBehaviour.ClientMembers.Length==0){Notified(2);return;}Channel=channel;}
 public void BeginTyping(){var p=ClientFrontend.ClientPlayerInstance;if(Writing||ClientFrontend.Pause||ClientFrontend.Hub||!p||!p.MyCharacter||p.MyCharacter.Health.CurrentHealth<=0)return;Writing=true;RiftControls.TextInputConsumedFrame=Time.frameCount;ChatBehaviour._instance?.SetTyping(true);oldPauseAllowed=UIPauseMenu._instance?UIPauseMenu._instance.AbleToPause:true;if(UIPauseMenu._instance)UIPauseMenu._instance.AbleToPause=false;UICursorManager.RequestCursor(gameObject);input.interactable=true;input.text="";EventSystem.current?.SetSelectedGameObject(input.gameObject);input.ActivateInputField();root.GetComponent<RiftMapSurface>().Fill=new Color(.025f,.026f,.04f,.82f);root.GetComponent<RiftMapSurface>().SetVerticesDirty();}
 public void EndTyping(bool send){if(!Writing)return;string text=input?input.text:"";Writing=false;ChatBehaviour._instance?.SetTyping(false);RiftControls.TextInputConsumedFrame=RiftControls.EscapeConsumedFrame=Time.frameCount;if(input){input.DeactivateInputField();input.text="";input.interactable=false;}if(EventSystem.current&&EventSystem.current.currentSelectedGameObject==(input?input.gameObject:null))EventSystem.current.SetSelectedGameObject(null);UICursorManager.ReleaseCursor(gameObject);if(UIPauseMenu._instance)UIPauseMenu._instance.AbleToPause=oldPauseAllowed;if(root){root.GetComponent<RiftMapSurface>().Fill=new Color(.025f,.026f,.04f,.32f);root.GetComponent<RiftMapSurface>().SetVerticesDirty();}if(send&&!string.IsNullOrWhiteSpace(text)&&ChatBehaviour._instance)ChatBehaviour._instance.CmdSendChannel(Channel,text);}
 void Update(){LegacyOff();bool connected=NetworkClient.isConnected&&!ClientFrontend.Hub;var p=ClientFrontend.ClientPlayerInstance;bool valid=connected&&p&&p.MyCharacter&&p.MyCharacter.Health.CurrentHealth>0;if(hadConnection&&!connected)ClearSession();hadConnection=connected;if(Writing&&(!valid||ClientFrontend.Pause||RiftVillageUI.Instance&&RiftVillageUI.Instance.TalkingTo||FindFirstObjectByType<RiftFieldUI>()?.MapOpen==true))EndTyping(false);var keyboard=Keyboard.current;if(Writing){if(keyboard!=null&&keyboard.escapeKey.wasPressedThisFrame)EndTyping(false);else if(keyboard!=null&&(keyboard.enterKey.wasPressedThisFrame||keyboard.numpadEnterKey.wasPressedThisFrame))EndTyping(true);}else if(valid&&!ClientFrontend.Pause&&!RiftControls.TextEntryFocused&&RiftControls.Pressed("Chat")&&UICursorManager.GamePlayInput())BeginTyping();if(Channel==1&&ChatBehaviour.ClientMembers.Length==0)Channel=0;partyChannel.interactable=ChatBehaviour.ClientMembers.Length>0;heading.text=Channel==1?"Party · "+ChatBehaviour.ClientMembers.Length+"/4":"Local · "+RiftSessionChatTuning.Load.Radius.ToString("0")+" m";if(Time.unscaledTime>=nextExpire){nextExpire=Time.unscaledTime+1;int removed=lines.RemoveAll(l=>Time.unscaledTime-l.At>RiftSessionChatTuning.Load.BufferSeconds);if(removed>0)RebuildHistory();}if(Time.unscaledTime>statusUntil)status.text="";if(invite&&NetworkTime.time>ChatBehaviour.InviteExpires){Destroy(invite.gameObject);invite=null;}UpdateBubbles();}
 void Receive(RiftChatLine data){lines.Add(new Line{Data=data,At=Time.unscaledTime});int max=Mathf.Clamp(RiftSessionChatTuning.Load.MaximumMemoryLines,8,100);if(lines.Count>max)lines.RemoveRange(0,lines.Count-max);RebuildHistory();var old=bubbles.FirstOrDefault(b=>data.Actor!=0?b.Data.Actor==data.Actor:b.Data.Npc==data.Npc);if(old!=null){Destroy(old.Root.gameObject);bubbles.Remove(old);}while(bubbles.Count>=6){Destroy(bubbles[0].Root.gameObject);bubbles.RemoveAt(0);}var rect=Rect(bubbleLayer,"Authorized speech bubble",0,0,230,62);rect.anchorMin=rect.anchorMax=new Vector2(.5f,.5f);rect.pivot=new Vector2(.5f,0);Surface(rect,.9f);var text=Label(rect,data.Name+"\n"+(data.Text.Length>88?data.Text.Substring(0,88)+"…":data.Text),8,4,214,54,12);text.alignment=TextAnchor.MiddleCenter;text.color=data.Channel==1?new Color(.68f,.85f,1):data.Channel==2?new Color(1,.86f,.57f):new Color(.94f,.93f,1);bubbles.Add(new Bubble{Data=data,Root=rect,Text=text,Until=Time.unscaledTime+RiftSessionChatTuning.Load.BubbleLifetime});}
 void RebuildHistory(){var b=new StringBuilder();foreach(var line in lines){var d=line.Data;b.Append(d.Channel==1?"[Party] ":d.Channel==2?"[NPC] ":"[Local] ").Append(d.Name).Append(": ").Append(d.Text).Append('\n');}history.text=b.ToString();Canvas.ForceUpdateCanvases();float height=Mathf.Max(76,history.preferredHeight);historyRoot.sizeDelta=new Vector2(324,height);history.rectTransform.sizeDelta=new Vector2(324,height);scroll.verticalNormalizedPosition=0;}
 void UpdateBubbles(){var camera=GameplayCamera._instance?GameplayCamera._instance.GetComponent<Camera>():null;var actor=ClientFrontend.OwnedCharacterInstance;foreach(var b in bubbles.ToArray()){if(Time.unscaledTime>=b.Until||!NetworkClient.isConnected){Destroy(b.Root.gameObject);bubbles.Remove(b);continue;}Vector3 point=b.Data.Position+Vector3.up*2.3f;bool exists=true;if(b.Data.Actor!=0){if(NetworkClient.spawned.TryGetValue(b.Data.Actor,out var id)&&id){var health=id.GetComponent<Health>();exists=!health||health.CurrentHealth>0;point=id.transform.position+Vector3.up*2.3f;}else exists=false;}else{var npc=RiftVillageNpc.Active.FirstOrDefault(n=>n&&n.Id==b.Data.Npc);if(npc)point=npc.Target&&npc.Target.Head?npc.Target.Head.position+Vector3.up*.45f:npc.transform.position+Vector3.up*2.5f;}var screen=camera?camera.WorldToScreenPoint(point):new Vector3(0,0,-1);bool visible=exists&&actor&&camera&&!(RiftVillageUI.Instance&&RiftVillageUI.Instance.VendorWindow)&&screen.z>0&&screen.x>15&&screen.x<Screen.width-15&&screen.y>20&&screen.y<Screen.height-20&&Vector3.Distance(actor.transform.position,point)<Mathf.Min(18,RiftSessionChatTuning.Load.Radius+3)&&!Physics.Linecast(camera.transform.position,point,GameManager.environmentLayer,QueryTriggerInteraction.Ignore);b.Root.gameObject.SetActive(visible);if(visible){RectTransformUtility.ScreenPointToLocalPointInRectangle(bubbleLayer,screen,null,out var local);b.Root.anchoredPosition=new Vector2(Mathf.Clamp(local.x,bubbleLayer.rect.xMin+118,bubbleLayer.rect.xMax-118),Mathf.Clamp(local.y+12,bubbleLayer.rect.yMin+4,bubbleLayer.rect.yMax-66));}}}
 void Notified(byte code){status.text=code==1?"Esperá un momento antes de enviar otro mensaje.":code==2?"Necesitás un grupo de sesión para usar Party.":code==3?"Seleccioná un jugador cercano y disponible.":code==4?"Ese jugador ya tiene una invitación pendiente.":code==5?"Solo el líder puede invitar; máximo cuatro miembros.":"La invitación venció o el grupo cambió.";statusUntil=Time.unscaledTime+4;}
 void PartyState(){if(party)RenderParty();if(invite)Destroy(invite.gameObject);invite=null;if(ChatBehaviour.InviteFrom==0)return;invite=Rect(hud.Design,"Session party invitation",20,0,340,72);invite.anchorMin=invite.anchorMax=invite.pivot=Vector2.zero;invite.anchoredPosition=new Vector2(20,310);Surface(invite,.95f);Label(invite,ChatBehaviour.InviteName+" te invita a su grupo",10,7,320,23,12);uint from=ChatBehaviour.InviteFrom,token=ChatBehaviour.InviteToken;Button(invite,"Aceptar",10,36,152,26,()=>ChatBehaviour._instance?.CmdAcceptParty(from,token));Button(invite,"Rechazar",174,36,152,26,()=>ChatBehaviour._instance?.CmdDeclineParty(token));}
