 public void InviteSelected(){var target=hud.SelectedTarget;var other=target?GameManager.Players.FirstOrDefault(p=>p&&p.MyCharacter&&p.MyCharacter.Health==target):null;if(other&&ChatBehaviour._instance)ChatBehaviour._instance.CmdInviteParty(other.netId);else Notified(3);}
 public void ClearSession(){EndTyping(false);lines.Clear();if(history)history.text="";foreach(var b in bubbles)if(b.Root)Destroy(b.Root.gameObject);bubbles.Clear();if(invite)Destroy(invite.gameObject);if(party)Destroy(party.gameObject);invite=party=null;}
